<script setup lang="ts">
import ConsoleDialog from '../console/ConsoleDialog.vue'
import {saveDecorationDraft,mergeDecorationDraft} from '../../utils/decoration-save'
import AdminConsole from '../console/AdminConsole.vue'
import ConsolePageHeading from '@orangezh1/qisvc-console-ui/components/ConsolePageHeading'
import ConsoleFormActions from '@orangezh1/qisvc-console-ui/components/ConsoleFormActions'
import ConsoleDiscardChangesDialog from '../console/ConsoleDiscardChangesDialog.vue'
import DecorationPreview from '../console/DecorationPreview.vue'
import PhonePreviewFrame from '../console/PhonePreviewFrame.vue'
import {defineConsoleAsyncComponent} from '../../utils/async-component'
const DecorationThemePanel=defineConsoleAsyncComponent(()=>import('../console/DecorationThemePanel.vue'),'主题面板')
const DecorationNavigationPanel=defineConsoleAsyncComponent(()=>import('../console/DecorationNavigationPanel.vue'),'底部导航')
import MaterialPicker from '../console/MaterialPicker.vue'
import {decorationTheme,inheritDecorationTheme,decorationNavigation,decorationPageBackground,normalizeDecorationScheme} from '../../../../api/src/core/decoration-contract.mjs'
import {decorationClone,type DecorationView,type DecorationRecord} from '../../utils/decoration'
const props=defineProps<{section:'theme'|'navigation'}>()
const auth=useApi('tenant'),tenantId=useTenantContext().tenantId.value,endpoint='/admin/tenants/'+encodeURIComponent(tenantId)+'/decoration',toast=useToast(),route=useRoute()
const initial=await useAsyncData('decoration-settings:'+props.section+':'+auth.session.value?.id+':'+tenantId,(_,{signal})=>auth.api<DecorationView>(endpoint,'GET',undefined,{signal}))
const data=ref<DecorationView|null>(initial.data.value||null),form=ref<DecorationRecord|null>(null),baseline=ref(''),busy=ref(''),error=ref(initial.error.value?.message||''),page=ref<'home'|'profile'>('home'),picker=ref(false),pickId=ref('')
const applied=computed(()=>!!form.value&&!!data.value?.published&&JSON.stringify(form.value.scheme)===JSON.stringify(normalizeDecorationScheme(data.value.published)))
const dirty=computed(()=>!!form.value&&JSON.stringify(form.value)!==baseline.value),locked=computed(()=>!!busy.value||!data.value?.canWrite),discard=useDiscardChanges(()=>!!busy.value),title=computed(()=>props.section==='theme'?'主题风格':'底部导航')
let disposed=false;const life=new AbortController()

function persistDraft(row:DecorationRecord,action:'save'|'save-and-activate'){const key=data.value!.applicationKey!;return saveDecorationDraft({base:JSON.parse(baseline.value) as DecorationRecord,local:row,version:data.value!.version,action,read:()=>auth.api<DecorationView>(endpoint+'?applicationKey='+encodeURIComponent(key),'GET',undefined,{signal:life.signal}),write:body=>auth.api<DecorationView>(endpoint+'/'+encodeURIComponent(key),'PUT',body,{signal:life.signal})})}
function acceptSaved(row:DecorationRecord,result:DecorationView){if(disposed||form.value?.id!==row.id)return;const saved=result.schemes.find(s=>s.id===row.id);if(!saved)return;const normalized={...saved,scheme:normalizeDecorationScheme(saved.scheme)};form.value=mergeDecorationDraft(row,form.value,normalized);data.value=result;baseline.value=JSON.stringify(normalized)}
function fill(id:string){const row=data.value?.schemes.find(s=>s.id===id);form.value=row?decorationClone(row):null;if(form.value)form.value.scheme=normalizeDecorationScheme(form.value.scheme);baseline.value=JSON.stringify(form.value);discard.keep()}
fill(data.value?.current?.id||data.value?.schemes[0]?.id||'')
function cancel(){fill(form.value?.id||'');error.value=''}
async function refresh(key=data.value?.applicationKey||'',action='refresh'){if(busy.value)return;if(dirty.value){discard.request(()=>{cancel();void refresh(key,action)});return}busy.value=action;if(disposed)return;error.value='';try{const result=await auth.api<DecorationView>(endpoint+(key?'?applicationKey='+encodeURIComponent(key):''),'GET',undefined,{signal:life.signal});if(disposed)return;const selected=form.value?.id;data.value=result;fill(result.schemes.find(s=>s.id===selected)?.id||result.activeId||result.schemes[0]?.id||'')}catch(e:any){if(!disposed)error.value=e.message}finally{if(!disposed)busy.value=''}}
async function save(){if(locked.value||!form.value||!data.value?.applicationKey)return;busy.value='save';error.value='';const row=decorationClone(form.value);try{const result=await persistDraft(row,'save');if(disposed)return;data.value=result;fill(row.id);toast.add({title:'已保存并生效',color:'success'})}catch(e:any){if(!disposed)error.value=e.message}finally{if(!disposed)busy.value=''}}
function pick(id:string){if(locked.value)return;pickId.value=id;picker.value=true}
function selected(image:{id:string}){const item=form.value?.scheme.navigation.items.find(i=>i.id===pickId.value);if(item)item.imageId=image.id}
function imageUrl(id:string){return '/api/v1/admin/tenants/'+encodeURIComponent(tenantId)+'/materials/'+encodeURIComponent(data.value?.applicationKey||'')+'/'+encodeURIComponent(id)+'/content?purpose=library'}
onBeforeRouteLeave(to=>{if(busy.value)return false;if(dirty.value){discard.request(()=>{cancel();void navigateTo(to.fullPath)});return false}})
function warnBeforeUnload(event:BeforeUnloadEvent){if(dirty.value||busy.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',warnBeforeUnload))
onBeforeUnmount(()=>{if(typeof window!=='undefined')window.removeEventListener('beforeunload',warnBeforeUnload);disposed=true;life.abort()})
</script>
<template><AdminConsole :refreshing="busy==='refresh'" @refresh="refresh()"><div class="decoration-settings-page"><ConsolePageHeading :title="title"/><UAlert v-if="error" color="warning" variant="subtle" :title="error"/><section class="decoration-settings-card overflow-hidden"><div class="flex flex-wrap items-center gap-3 p-5 border-b border-default"><strong class="text-sm">当前装修</strong><USelect v-if="data&&data.applications.length>1" :model-value="data.applicationKey||undefined" :items="data.applications.map(a=>({value:a.key,label:a.name}))" :disabled="!!busy" :loading="busy==='switch'" aria-label="选择应用" class="w-44" @update:model-value="refresh(String($event),'switch')"/><span class="draft-save-status"><UIcon name="i-lucide-cloud-check"/>{{dirty?'未保存修改':data?.currentSaved===false?'默认内容，尚未保存':'已保存'}}</span></div><form v-if="form" class="decoration-settings-form" @submit.prevent="save()"><div class="decoration-settings-body"><div class="settings-preview"><div class="flex gap-2 mb-5"><UButton :variant="page==='home'?'solid':'ghost'" size="sm" color="neutral" @click="page='home'">首页</UButton><UButton :variant="page==='profile'?'solid':'ghost'" size="sm" color="neutral" @click="page='profile'">个人中心</UButton></div><div class="settings-phone"><PhonePreviewFrame :bottom-color="form.scheme.navigation.enabled?decorationNavigation(form.scheme).background:decorationPageBackground(form.scheme,page)"><DecorationPreview :scheme="form.scheme" :page="page" :image-url="imageUrl" @navigate="($event==='home'||$event==='profile')&&(page=$event)"/></PhonePreviewFrame></div></div><div class="settings-editor"><DecorationThemePanel v-if="section==='theme'&&form.scheme.theme" v-model="form.scheme.theme" :disabled="locked" @inherit-all="inheritDecorationTheme(form.scheme)"/><DecorationNavigationPanel v-else v-model="form.scheme.navigation" :targets="data?.targets||[]" :disabled="locked" :image-url="imageUrl" @pick="pick"/></div></div><div class="settings-actions p-4 border-t border-default"><ConsoleFormActions><span class="mr-auto text-xs text-muted">修改仅在当前页面预览，保存后生效。</span><UButton color="neutral" variant="outline" :disabled="!!busy||!dirty" @click="discard.request(cancel)">取消修改</UButton><UButton type="submit" :disabled="locked||(!dirty&&applied&&data?.currentSaved!==false)" :loading="busy==='save'">保存</UButton></ConsoleFormActions></div></form><div v-else class="p-12 text-center space-y-5"><p class="text-sm text-muted">先选择已开通的应用，再设置{{title}}。</p><UButton to="/admin/decoration">去页面装修</UButton></div></section><ConsoleDiscardChangesDialog :controller="discard"/><MaterialPicker v-model:open="picker" portal="tenant" purpose="library" kind="image" :endpoint="'/admin/tenants/'+encodeURIComponent(tenantId)+'/materials/'+encodeURIComponent(data?.applicationKey||'')" @select="selected"/></div></AdminConsole></template>
<style scoped>.settings-scheme{border:1px solid var(--ui-border);border-radius:6px;padding:7px 10px;background:var(--ui-bg);font-size:13px;max-width:100%}.decoration-settings-body{display:grid;grid-template-columns:minmax(320px,1fr) minmax(300px,440px)}.settings-preview{background:var(--ui-bg-elevated);padding:28px;display:flex;flex-direction:column;align-items:center;min-width:0}.settings-preview :deep(.decoration-preview){width:100%;max-width:375px;border:1px solid var(--ui-border);border-radius:16px;min-height:640px}.settings-editor{padding:28px;border-left:1px solid var(--ui-border);min-width:0}@media(max-width:800px){.decoration-settings-body{grid-template-columns:1fr}.settings-editor{border-left:0;border-top:1px solid var(--ui-border);padding:20px}.settings-preview{padding:20px}}.decoration-settings-page{display:flex;flex-direction:column;gap:16px;flex:1;min-height:0}.decoration-settings-card{display:flex;flex-direction:column;flex:1;min-height:0}.decoration-settings-card>div:first-child{flex-shrink:0;padding:12px 20px}.decoration-settings-form{display:flex;flex-direction:column;flex:1;min-height:0}.decoration-settings-body{flex:1;min-height:0;overflow:hidden;grid-template-columns:minmax(280px,1fr) minmax(300px,420px)}.settings-preview{height:100%;min-height:0;overflow:hidden;padding:18px;display:flex;flex-direction:column}.settings-preview>div:first-child{flex-shrink:0;margin-bottom:14px}.settings-phone{flex:1;min-height:0;width:100%}.settings-preview :deep(.decoration-preview){min-height:0;max-width:none}.settings-editor{overflow-y:auto;min-height:0;padding:22px 24px}.settings-actions{flex-shrink:0}.settings-actions :deep(.qisvc-console-form-actions){flex-wrap:wrap}@media(max-width:800px){.decoration-settings-body{grid-template-columns:minmax(220px,1fr) minmax(260px,1fr)}.settings-editor{padding:18px}.settings-preview{padding:12px}}@media(max-width:600px){.decoration-settings-body{grid-template-columns:1fr;grid-template-rows:minmax(160px,40%) minmax(180px,60%)}.settings-preview{padding:8px;min-height:0}.settings-preview>div:first-child{margin-bottom:6px}.settings-editor{padding:16px}.settings-actions{padding:10px}.settings-actions :deep(.mr-auto){width:100%;margin-bottom:4px}.decoration-settings-page{gap:10px}}
.decoration-settings-card{border:0;border-radius:0;box-shadow:none;background:transparent}.decoration-settings-card>div:first-child{border:0;padding:4px 0 16px}.decoration-settings-body{grid-template-columns:minmax(280px,460px) minmax(300px,480px);justify-content:center;gap:44px}.settings-preview{background:transparent;padding:0 20px 14px}.settings-editor{border-left:0;background:transparent;padding:2px 18px 24px}.settings-actions{padding:14px 0 0;background:var(--ui-bg)}@media(max-width:1100px){.decoration-settings-body{grid-template-columns:minmax(260px,1fr) minmax(280px,1fr);gap:24px}.settings-preview{padding:0 8px 12px}.settings-editor{padding:0 6px 20px}}@media(max-width:600px){.decoration-settings-body{grid-template-columns:1fr;gap:12px}.settings-editor{border-top:1px solid var(--ui-border);padding:16px 4px}.settings-actions{padding-top:10px}}
.draft-save-status{display:inline-flex;align-items:center;gap:5px;font-size:11px;color:var(--ui-text-muted)}.draft-save-status button{color:var(--ui-primary);margin-left:5px}
.settings-preview :deep(.decoration-preview){border:0;border-radius:0;box-shadow:none;min-height:0}
</style>
